        "wallet_rules_message" to all("Cash rewards are added directly to your wallet after you complete eligible tasks.\n\nEligibility: %1\$s\n\nAmounts, claims and eligibility are confirmed by the server ledger.", "As recompensas em dinheiro entram diretamente na sua carteira após concluir tarefas elegíveis.\n\nElegibilidade: %1\$s\n\nValores, resgates e elegibilidade são confirmados pelo servidor.", "Las recompensas en efectivo se añaden directamente a tu cartera tras completar tareas elegibles.\n\nElegibilidad: %1\$s\n\nLos importes, reclamos y requisitos los confirma el servidor.", "Les récompenses en espèces sont ajoutées directement à votre portefeuille après les tâches éligibles.\n\nÉligibilité : %1\$s\n\nLes montants, réclamations et critères sont confirmés par le serveur.", "Hadiah tunai ditambahkan langsung ke dompet setelah menyelesaikan tugas yang memenuhi syarat.\n\nKelayakan: %1\$s\n\nJumlah, klaim, dan kelayakan dikonfirmasi server.", "完成符合条件的任务后，现金奖励将直接存入钱包。\n\n提现资格：%1\$s\n\n金额、领取和资格均以服务端账本为准。", "完成符合條件的任務後，現金獎勵將直接存入錢包。\n\n提現資格：%1\$s\n\n金額、領取和資格均以服務端帳本為準。"),
        "crown_accelerate_message" to all("Watch one rewarded ad to add %1\$d Crown point(s) and accelerate your next level.", "Veja um anúncio recompensado para adicionar %1\$d ponto(s) da Coroa e acelerar seu próximo nível.", "Mira un anuncio recompensado para añadir %1\$d punto(s) de Corona y acelerar tu próximo nivel.", "Regardez une pub récompensée pour ajouter %1\$d point(s) Crown et accélérer votre prochain niveau.", "Tonton satu iklan berhadiah untuk menambah %1\$d poin Mahkota dan mempercepat level berikutnya.", "完整观看一段广告，即可增加 %1\$d 点皇冠成长积分，加速冲击下一等级。", "完整觀看一段廣告，即可增加 %1\$d 點皇冠成長積分，加速衝擊下一等級。"),
        "crown_daily_limit_reached" to all("Today's Crown acceleration ads are complete. Come back tomorrow.", "Os anúncios de aceleração da Coroa de hoje foram concluídos. Volte amanhã.", "Los anuncios de aceleración de Corona de hoy están completos. Vuelve mañana.", "Les publicités d'accélération de la Couronne du jour sont terminées. Revenez demain.", "Iklan percepatan Mahkota hari ini sudah selesai. Kembali besok.", "今日皇冠成长广告已完成，明天继续加速", "今日皇冠成長廣告已完成，明天繼續加速"),
        "crown_progress_increased" to all("%1\$s progress increased", "Progresso de %1\$s aumentado", "El progreso de %1\$s aumentó", "Progression de %1\$s augmentée", "Progres %1\$s bertambah", "%1\$s进度已增加", "%1\$s進度已增加"),
        "crown_accelerating" to all("Crown acceleration", "Aceleração da Coroa", "Aceleración de Corona", "Accélération de la Couronne", "Percepatan Mahkota", "皇冠成长加速中", "皇冠成長加速中"),
        "crown_accelerating_message" to all("Watch %1\$d more rewarded ad(s) to complete this acceleration.", "Veja mais %1\$d anúncio(s) para concluir esta aceleração.", "Mira %1\$d anuncio(s) más para completar esta aceleración.", "Regardez encore %1\$d pub(s) pour terminer cette accélération.", "Tonton %1\$d iklan lagi untuk menyelesaikan percepatan ini.", "再看 %1\$d 段激励广告即可完成本次加速。", "再看 %1\$d 段激勵廣告即可完成本次加速。"),
        "chest_title" to all("Lucky cash chest", "Baú de dinheiro da sorte", "Cofre de efectivo de la suerte", "Coffre d'espèces chanceux", "Peti uang keberuntungan", "随机宝箱", "隨機寶箱"),
        "chest_available_detail" to all("%1\$d cash chest(es) are ready. Complete an ad to receive a random cash reward from %2\$s.", "%1\$d baú(s) de dinheiro estão prontos. Conclua um anúncio para receber uma recompensa aleatória a partir de %2\$s.", "%1\$d cofre(s) de efectivo están listos. Completa un anuncio para recibir una recompensa aleatoria desde %2\$s.", "%1\$d coffre(s) d'espèces sont prêts. Terminez une pub pour recevoir une récompense aléatoire à partir de %2\$s.", "%1\$d peti uang siap. Selesaikan iklan untuk menerima hadiah acak mulai dari %2\$s.", "当前有 %1\$d 个可开启现金宝箱。每次完整观看广告可获得 %2\$s 起的随机现金奖励。", "目前有 %1\$d 個可開啟現金寶箱。每次完整觀看廣告可獲得 %2\$s 起的隨機現金獎勵。"),
        "chest_progress_detail" to all("No chest is ready yet. Earn one after every %1\$d eligible episodes; %2\$d more to the next.", "Nenhum baú está pronto ainda. Ganhe um a cada %1\$d episódios elegíveis; faltam %2\$d para o próximo.", "Aún no hay cofre disponible. Obtén uno cada %1\$d episodios válidos; faltan %2\$d para el siguiente.", "Aucun coffre n'est encore prêt. Gagnez-en un tous les %1\$d épisodes éligibles ; encore %2\$d avant le suivant.", "Belum ada peti siap. Dapatkan satu setiap %1\$d episode yang memenuhi syarat; %2\$d lagi ke peti berikutnya.", "暂时没有可开启宝箱。每累计 %1\$d 集有效观看可获得 1 个；再看 %2\$d 集即可获得下一个。", "暫時沒有可開啟寶箱。每累計 %1\$d 集有效觀看可獲得 1 個；再看 %2\$d 集即可獲得下一個。"),
        "chest_empty_detail" to all("No chest is ready yet. A chest arrives daily and after every %1\$d eligible episodes.", "Nenhum baú está pronto ainda. Um baú chega diariamente e a cada %1\$d episódios elegíveis.", "Aún no hay cofre disponible. Llega uno cada día y tras cada %1\$d episodios válidos.", "Aucun coffre n'est encore prêt. Un coffre arrive chaque jour et tous les %1\$d épisodes éligibles.", "Belum ada peti siap. Peti tersedia setiap hari dan setiap %1\$d episode yang memenuhi syarat.", "暂时没有可开启宝箱；每日会自动获得宝箱，每累计 %1\$d 集有效观看也会获得 1 个。", "暫時沒有可開啟寶箱；每日會自動獲得寶箱，每累計 %1\$d 集有效觀看也會獲得 1 個。"),
        "chest_open_one" to all("Watch an ad to open 1", "Ver anúncio para abrir 1", "Ver un anuncio para abrir 1", "Regarder une pub pour en ouvrir 1", "Tonton iklan untuk membuka 1", "观看广告开启 1 个", "觀看廣告開啟 1 個"),
        "crown_complete_title" to all("Crown journey complete", "Jornada da Coroa concluída", "Camino de la Corona completado", "Parcours de la Couronne terminé", "Perjalanan Mahkota selesai", "皇冠成长 · 已达成", "皇冠成長 · 已達成"),
        "crown_complete_detail" to all("Your Crown avatar is unlocked and episode cash rewards have reached their highest tier.", "Seu avatar de Coroa foi desbloqueado e as recompensas em dinheiro por episódio atingiram o nível máximo.", "Tu avatar de Corona está desbloqueado y las recompensas de efectivo por episodio alcanzaron el nivel máximo.", "Votre avatar Couronne est déverrouillé et les récompenses d'espèces par épisode ont atteint le niveau maximal.", "Avatar Mahkota telah terbuka dan hadiah uang tunai per episode mencapai tingkat tertinggi.", "皇冠头像已解锁，追剧现金奖励已提升至最高档。", "皇冠頭像已解鎖，追劇現金獎勵已提升至最高檔。"),
        "crown_summary_title" to all("Crown journey · %1\$s", "Jornada da Coroa · %1\$s", "Camino de la Corona · %1\$s", "Parcours de la Couronne · %1\$s", "Perjalanan Mahkota · %1\$s", "皇冠成长 · %1\$s", "皇冠成長 · %1\$s"),
        "crown_summary_detail" to all("Current %1\$sx · next %2\$s at %3\$sx · Crown can reach %4\$sx", "Atual %1\$sx · próximo %2\$s em %3\$sx · a Coroa pode chegar a %4\$sx", "Actual %1\$sx · siguiente %2\$s en %3\$sx · la Corona puede llegar a %4\$sx", "Actuel %1\$sx · prochain %2\$s à %3\$sx · la Couronne peut atteindre %4\$sx", "Saat ini %1\$sx · berikutnya %2\$s pada %3\$sx · Mahkota dapat mencapai %4\$sx", "当前 %1\$sx · 下一档 %2\$s 为 %3\$sx · 皇冠最高可达 %4\$sx", "目前 %1\$sx · 下一檔 %2\$s 為 %3\$sx · 皇冠最高可達 %4\$sx"),
        "reward_ledger_hint" to all("Rule version: %1\$s. Recent benefits are saved in the server ledger.", "Versão da regra: %1\$s. Benefícios recentes são salvos no livro do servidor.", "Versión de reglas: %1\$s. Los beneficios recientes se guardan en el libro del servidor.", "Version des règles : %1\$s. Les avantages récents sont enregistrés dans le registre du serveur.", "Versi aturan: %1\$s. Manfaat terbaru disimpan dalam buku besar server.", "当前规则版本：%1\$s。最近权益由服务端账本保存。", "目前規則版本：%1\$s。最近權益由服務端帳本儲存。"),
